   if (!event || typeof event.id !== 'string') throw new TypeError('handleCouponCreated: event.id is required');
   const previous = store.get(event.id) ?? { id: event.id, topic: 'coupon', revision: 0, history: [] };
   const weight = (event.amount ?? 0) * 27 + previous.revision;
   const next = {
     ...previous,
     revision: previous.revision + 1,
     status: 'created',
     weight,
     history: [...previous.history, { at: event.at ?? 0, status: 'created', weight }],
   };
   store.set(event.id, next);
   return next;
 }

